#!/usr/bin/env bash
# update-it-atlas.sh: upgrades your NOC Atlas or IT Atlas vault to the IT Atlas, and updates the
# IT Atlas (Gesture Graph) plugin. macOS or Linux. Run:  bash ~/Downloads/update-it-atlas.sh
#
#   bash update-it-atlas.sh                  finds ~/Documents/IT-Atlas or ~/Documents/NOC-Atlas
#   bash update-it-atlas.sh "/path/to/vault" updates that vault
#
# What it does:
#   1. Copies the whole vault to a timestamped backup folder first.
#   2. Replaces the generated notes with the new versions and adds the new Help Desk notes.
#      Text you wrote under "## Field notes" in a note is carried over into the new version.
#   3. Removes old generated notes that were renamed (for example the old week names).
#      Notes you created yourself are never touched.
#   4. Keeps your Obsidian settings and plugins; refreshes the graph colours and bookmarks.
#   5. Installs the new plugin version, keeping its settings and downloaded hand model.
set -euo pipefail

if [ -t 1 ]; then B=$'\e[1m'; G=$'\e[32m'; Y=$'\e[33m'; R=$'\e[31m'; N=$'\e[0m'; else B=; G=; Y=; R=; N=; fi
step() { printf "\n${B}==> %s${N}\n" "$*"; }
ok()   { printf "   ${G}✓${N} %s\n" "$*"; }
warn() { printf "   ${Y}!${N} %s\n" "$*"; }
die()  { printf "   ${R}✗ %s${N}\n" "$*"; exit 1; }

VAULT="${1:-}"
if [ -z "$VAULT" ]; then
  for v in "$HOME/Documents/IT-Atlas" "$HOME/Documents/NOC-Atlas" "$HOME/NOC-Atlas" "$HOME/IT-Atlas"; do
    [ -d "$v/.obsidian" ] && { VAULT="$v"; break; }
  done
fi
[ -n "$VAULT" ] || die "Couldn't find your atlas vault. Run: bash update-it-atlas.sh \"/path/to/NOC-Atlas\""
[ -d "$VAULT/.obsidian" ] || die "$VAULT is not an Obsidian vault (no .obsidian folder)."
VAULT="$(cd "$VAULT" && pwd)"
SELF="${BASH_SOURCE[0]}"
TS="$(date +%Y%m%d-%H%M%S)"

if pgrep -xi obsidian >/dev/null 2>&1; then
  warn "Obsidian is open. Quit it first (Cmd+Q) so it doesn't hold old copies of notes, then run this again."
  [ -t 0 ] && { read -r -p "   Continue anyway? [y/N] " a; [[ "$a" =~ ^[Yy] ]] || exit 1; } || exit 1
fi

step "Backing up $VAULT"
BAK="$VAULT.backup-$TS"
cp -R "$VAULT" "$BAK"
ok "Backup at $BAK"

step "Unpacking the IT Atlas"
if printf 'QQ==' | base64 --decode >/dev/null 2>&1; then B64D="base64 --decode"; else B64D="base64 -D"; fi
TMP="$(mktemp -d)"; trap 'rm -rf "$TMP"' EXIT
sed -n '/^__PAYLOAD_BELOW__$/,$p' "$SELF" | tail -n +2 | $B64D | tar -xz -C "$TMP" || die "Couldn't unpack (is the script complete?)"
NEW="$TMP/IT-Atlas"; PLUG="$TMP/gesture-graph"
[ -d "$NEW" ] && [ -d "$PLUG" ] || die "Unpacked data is incomplete."
ok "$(find "$NEW" -name '*.md' | wc -l | tr -d ' ') notes ready"

# Prints the user's own lines from a note's "## Field notes" section (nothing if untouched).
field_notes() {
  awk 'BEGIN{f=0} /^## Field notes[[:space:]]*$/{f=1; next} f && /^## /{f=0} f' "$1" \
    | grep -v -e '^Add your own tips' -e '^[[:space:]]*$' || true
}

step "Updating notes"
GEN="$NEW/_system/generated-files.txt"
updated=0; added=0; kept=0; removed=0
while IFS= read -r -d '' f; do
  rel="${f#"$NEW"/}"
  dst="$VAULT/$rel"
  mkdir -p "$(dirname "$dst")"
  if [ -f "$dst" ] && [[ "$rel" == *.md ]]; then
    # only lines the user added: drop anything the new version already has in that section
    mine="$(field_notes "$dst" | grep -vxF -f <(field_notes "$f"; echo '__none__') || true)"
    cp "$f" "$dst"
    if [ -n "$mine" ]; then
      if grep -q '^## Field notes' "$dst"; then printf '%s\n' "$mine" >> "$dst"
      else printf '\n## Field notes\n\n%s\n' "$mine" >> "$dst"; fi
      kept=$((kept+1))
    fi
    updated=$((updated+1))
  else
    cp "$f" "$dst"; [[ "$rel" == *.md ]] && added=$((added+1))
  fi
done < <(cd "$NEW" && find "$NEW" -type f ! -path "$NEW/.obsidian/*" -print0)

# Old generated notes that no longer exist (renamed in this version): remove them (they're in the backup).
while IFS= read -r rel; do
  [ -n "$rel" ] || continue
  if [ -f "$VAULT/$rel" ] && [ ! -f "$NEW/$rel" ]; then
    mine="$(field_notes "$VAULT/$rel")"
    if [ -n "$mine" ]; then warn "Kept $rel (it has your Field notes; it was renamed in this version)"; continue; fi
    rm -f "$VAULT/$rel"; removed=$((removed+1))
  fi
done < "$GEN"
find "$VAULT" -type d -empty ! -path "*/.git/*" ! -path "*/.obsidian/*" -delete 2>/dev/null || true
ok "$updated notes updated, $added new, $removed old ones removed"
[ "$kept" -gt 0 ] && ok "Carried over your Field notes in $kept note(s)"

step "Refreshing Obsidian settings"
for c in graph.json bookmarks.json templates.json; do cp "$NEW/.obsidian/$c" "$VAULT/.obsidian/$c"; done
ok "Graph colours (including the new Help Desk colour) and bookmarks updated; your plugins and other settings are untouched"

step "Updating the IT Atlas plugin"
P="$VAULT/.obsidian/plugins/gesture-graph"; mkdir -p "$P"
cp -R "$PLUG/." "$P/"
CP="$VAULT/.obsidian/community-plugins.json"
ids=(); [ -f "$CP" ] && while IFS= read -r x; do [ -n "$x" ] && ids+=("$x"); done < <(grep -o '"[^"]*"' "$CP" | tr -d '"')
found=0; for x in "${ids[@]+"${ids[@]}"}"; do [ "$x" = gesture-graph ] && found=1; done
[ $found = 1 ] || ids+=("gesture-graph")
{ printf '['; first=1; for x in "${ids[@]}"; do [ $first = 1 ] && first=0 || printf ','; printf '\n  "%s"' "$x"; done; printf '\n]\n'; } > "$CP"
ok "Plugin $(sed -n 's/.*"version": *"\([^"]*\)".*/\1/p' "$P/manifest.json") installed and enabled"

# The work vault gets the plugin too, if it has it already.
for w in "$HOME/Documents/Rehan-Vault" "$HOME/Rehan-Vault"; do
  if [ -d "$w/.obsidian/plugins/gesture-graph" ]; then cp -R "$PLUG/." "$w/.obsidian/plugins/gesture-graph/"; ok "Plugin also updated in $w"; fi
done

step "Done"
cat <<EOF
   Vault:   $VAULT  (backup: $BAK)
   Open Obsidian, then click the brain icon in the left ribbon for the IT Atlas.
   New:     828 pages: 76 everyday fixes, 348 tools, 133 concepts, 48 playbooks,
            Junior/Mid/Senior levels, career tracks and two new lobes (DevOps, Compliance).
   If something looks wrong, the backup folder above is a complete copy of your old vault.
EOF
exit 0
